// Stand-alone tests for ofxAudioFile (no openFrameworks needed).
//   make -C tests          builds with AddressSanitizer and runs
// Test files are generated by make_test_files.sh (needs ffmpeg).

#include "../src/ofxAudioFile.h"

#include <cmath>
#include <cstdio>
#include <string>

static int failures = 0;
static void check(bool ok, const std::string & what) {
    if (!ok) { std::printf("FAIL: %s\n", what.c_str()); ++failures; }
}

// Every test file is 0.5 s of a 441 Hz sine at 44.1 kHz, stereo, amplitude 0.5.
static void checkFile(const std::string & path, bool lossy) {
    ofxAudioFile file;
    file.load(path);
    check(file.loaded(), path + " loads");
    if (!file.loaded()) return;
    check(file.channels() == 2, path + " has 2 channels");
    check(file.samplerate() == 44100, path + " is 44100 Hz");
    // mp3 adds encoder delay/padding, so allow a margin on length.
    uint64_t expected = 22050;
    uint64_t margin = lossy ? 4000 : 0;
    check(file.length() + margin >= expected && file.length() <= expected + margin, path + " length");
    float peak = 0.0f;
    for (uint64_t n = 0; n < file.length(); ++n) peak = std::fmax(peak, std::fabs(file.sample((int)n, 0)));
    check(std::fabs(peak - 0.5f) < (lossy ? 0.08f : 0.01f), path + " peak about 0.5");

    ofxAudioFile copy(file);                 // copy constructor
    check(copy.loaded() && copy.length() == file.length(), path + " copy");
    ofxAudioFile assigned;
    assigned = file;                         // assignment
    assigned = assigned;                     // self assignment must be harmless
    check(assigned.loaded() && assigned.sample(100, 1) == file.sample(100, 1), path + " assign");
    for (int i = 0; i < 20; ++i) file.load(path); // repeated reloads must not leak
    file.free();
    check(!file.loaded() && file.length() == 0, path + " free");
}

int main() {
    checkFile("data/tone.wav", false);
    checkFile("data/tone.flac", false);
    checkFile("data/tone.ogg", true);
    checkFile("data/tone.mp3", true);
    ofxAudioFile missing;
    missing.load("data/does_not_exist.wav");
    check(!missing.loaded(), "missing file is not loaded");
    missing.load("data/no_extension");
    check(!missing.loaded(), "file without extension is rejected");
    std::printf(failures == 0 ? "ofxAudioFile tests: all passed\n" : "ofxAudioFile tests: %d failure(s)\n", failures);
    return failures == 0 ? 0 : 1;
}
